162	std::pair<Address::InstanceConstSharedPtr, Network::IoHandlePtr>
163	bindFreeLoopbackPort(Address::IpVersion version, Address::SocketType type) {
164	  Address::InstanceConstSharedPtr addr = getCanonicalLoopbackAddress(version);
165	  IoHandlePtr io_handle = addr->socket(type);
166	  Api::SysCallIntResult result = addr->bind(io_handle->fd());
167	  if (0 != result.rc_) {
168	    io_handle->close();
169	    std::string msg = fmt::format("bind failed for address {} with error: {} ({})",
170	                                  addr->asString(), strerror(result.errno_), result.errno_);
171	    ADD_FAILURE() << msg;
172	    throw EnvoyException(msg);
173	  }
174	  return std::make_pair(Address::addressFromFd(io_handle->fd()), std::move(io_handle));
175	}
