131	// Verifies calling sendmsg with a non-local address. Note that this test is only fully complete for
132	// IPv4. See the comment below for more details.
133	TEST_P(UdpProxyIntegrationTest, HelloWorldOnNonLocalAddress) {
134	  setup(1);
135	  const uint32_t port = lookupPort("listener_0");
136	  Network::Address::InstanceConstSharedPtr listener_address;
137	  if (version_ == Network::Address::IpVersion::v4) {
138	    // Kernel regards any 127.x.x.x as local address.
139	    listener_address.reset(new Network::Address::Ipv4Instance(
140	#ifndef __APPLE__
141	        "127.0.0.3",
142	#else
143	        "127.0.0.1",
144	#endif
145	        port));
146	  } else {
147	    // IPv6 doesn't allow any non-local source address for sendmsg. And the only
148	    // local address guaranteed in tests in loopback. Unfortunately, even if it's not
149	    // specified, kernel will pick this address as source address. So this test
150	    // only checks if IoSocketHandle::sendmsg() sets up CMSG_DATA correctly,
151	    // i.e. cmsg_len is big enough when that code path is executed.
152	    listener_address.reset(new Network::Address::Ipv6Instance("::1", port));
153	  }
154	
155	  requestResponseWithListenerAddress(*listener_address);
156	}
